typedef unsigned int uint32_t;
void hero_mm_tile_scalar(const uint32_t *a_local, const uint32_t *b_local,
                         uint32_t *c_local, uint32_t width,
                         uint32_t stripe_height, uint32_t t) {
  for (uint32_t i = 0; i < stripe_height; ++i) {
    for (uint32_t j = 0; j < stripe_height; ++j) {
      uint32_t sum = 0;
      for (uint32_t k = 0; k < width; ++k)
        sum = sum + a_local[i*width+k] * b_local[j*width+k];
      c_local[i*width+t*stripe_height+j] = sum;
    }
  }
}
