typedef unsigned long u64;
u64 kernel_cycle(void) { u64 c; __asm__ volatile("csrr %0, mcycle" : "=r"(c) :: "memory"); return c; }
void kernel_fir_fixed(const i32 *input, const i32 *coeff, i32 *output, u32 samples, u32 taps) { for(u32 n=0;n<samples;++n) { i64 sum=0; for(u32 k=0;k<taps;++k) sum+=(i64)input[n+k]*(i64)coeff[k]; output[n]=(i32)(sum>>15); } }
void kernel_matmul_fixed(const i32 *a, const i32 *b, i32 *c, u32 n) { for(u32 i=0;i<n;++i) for(u32 j=0;j<n;++j) { i64 sum=0; for(u32 k=0;k<n;++k) sum+=(i64)a[i*n+k]*(i64)b[k*n+j]; c[i*n+j]=(i32)(sum>>15); } }
